private static CronDefinition quartz() {
    return CronDefinitionBuilder.defineCron()
            .withSeconds().withStrictRange().and()
            .withMinutes().withStrictRange().and()
            .withHours().withStrictRange().and()
            .withDayOfMonth()
                .withValidRange(1, 31)
                .supports(SpecialChar.L)  // Supports 'L' for last day of the month
                .supports(SpecialChar.W)  // Supports 'W' for nearest weekday
                .supports(SpecialChar.QUESTION_MARK)  // Supports '?' for no specific value
                .withStrictRange().and()
            .withMonth().withValidRange(1, 12).withStrictRange().and()
            .withDayOfWeek()
                .withValidRange(1, 7)
                .withMondayDoWValue(2)
                .supports(SpecialChar.L)  // Supports 'L' for last day of the week
                .supports(SpecialChar.HASH)  // Supports '#' for nth day of the week
                .supports(SpecialChar.QUESTION_MARK)  // Supports '?' for no specific value
                .and()
            .withYear().withValidRange(1970, 2099).withStrictRange().optional().and()
            .withCronValidation(CronConstraintsFactory.ensureEitherDayOfWeekOrDayOfMonth())
            .instance();
}

